insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m091', 'k-central', 2, 'الدرجات التالية تمثل نتائج سبعة طلاب في اختبار قصير: 5، 8، 6، 9، 7، 4، 10. ما الوسيط لهذه الدرجات؟', '["6","7","8","9"]'::jsonb, 1, 'نرتب القيم تصاعديًا: 4، 5، 6، 7، 8، 9، 10. وعدد القيم فردي فالوسيط هو القيمة الوسطى (الرابعة) = 7.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m092', 'k-central', 2, 'أوجد الوسيط للأعداد التالية: 11، 7، 5، 8، 2، 3', '["4","5","6","7"]'::jsonb, 2, 'بعد الترتيب: 2، 3، 5، 7، 8، 11. وعدد القيم زوجي فالوسيط = متوسط القيمتين الوسطيتين = (5 + 7) ÷ 2 = 6.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m093', 'k-central', 2, 'أي من العبارات الآتية لا تُعد من خصائص الوسيط؟', '["لا يتأثر بالقيم المتطرفة العالية أو المنخفضة","يُستخدم مع البيانات الاسمية والرتبية","لا تدخل جميع القيم في حسابه","غير مناسب للمفردات القليلة أو المكررة"]'::jsonb, 1, 'الوسيط يصلح للبيانات الرتبية والكمية، أما البيانات الاسمية (كالألوان والتخصصات) فلا يمكن ترتيبها، والمنوال هو المقياس الوحيد الصالح لها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m094', 'k-central', 2, 'مقياس النزعة المركزية المناسب لوصف الرياضة المحببة بشكل أكبر للطلاب هو:', '["المتوسط الحسابي","الوسيط","المنوال","المدى"]'::jsonb, 2, 'أسماء الرياضات بيانات اسمية لا تقبل الحساب ولا الترتيب، والمنوال (الأكثر تكرارًا) هو المقياس الوحيد الذي يصلح معها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m095', 'k-central', 3, 'أي من الخيارات التالية لا يمكن استخدام كل مقاييس النزعة المركزية معها؟', '["أطوال طلاب المدرسة","دخل أسر الطلاب الشهري","تقديرات الطلاب في الرياضيات","درجات الطلاب في الفيزياء"]'::jsonb, 2, 'التقديرات (ممتاز، جيد جدًا...) بيانات رتبية يصلح معها المنوال والوسيط دون المتوسط الحسابي، بخلاف البيانات الكمية التي تصلح معها المقاييس الثلاثة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m096', 'k-central', 3, 'أي مقاييس النزعة المركزية تناسب أكثر هذه القيم: 2، 4، 6، 3، 8، 22؟', '["المتوسط الحسابي","الوسيط","المنوال","المدى"]'::jsonb, 1, 'القيمة 22 متطرفة وترفع المتوسط فيصبح مضللًا، والوسيط لا يتأثر بالقيم الشاذة فهو الأنسب. (المدى مقياس تشتت لا نزعة مركزية).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m097', 'k-central', 2, 'قيمة أي مقياس للتشتت لا بد أن تكون:', '["موجبة فقط","سالبة فقط","موجبة أو صفر","موجبة أو سالبة"]'::jsonb, 2, 'مقاييس التشتت تقيس مقدار التباعد وهو لا يكون سالبًا، وتساوي صفرًا حين تتطابق جميع القيم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m098', 'k-central', 1, 'الدرجات التالية تمثل نتائج خمسة طلاب في اختبار العلوم: 6، 9، 7، 5، 10. ما المدى لهذه الدرجات؟', '["4","5","6","7"]'::jsonb, 1, 'المدى = أعلى قيمة − أدنى قيمة = 10 − 5 = 5.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m099', 'k-central', 2, 'تتكوّن مجموعة من البيانات من 15 قيمة متدرجة، ويبلغ مداها 5، ووفقًا لما ورد في سجل البيانات كانت أصغر قيمة فيها تساوي 7. فما القيمة الأكبر؟', '["10","11","12","13"]'::jsonb, 2, 'من قانون المدى: أعلى قيمة = المدى + أدنى قيمة = 5 + 7 = 12. ولا أثر لعدد القيم في الحساب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m100', 'k-central', 3, 'تمثّل الأعداد التالية درجات مجموعة من الطلاب في اختبار العلوم: 9، 5، 12، 7، 10، 6، 8. ما المدى الربيعي لهذه الدرجات؟', '["4","5","6","3"]'::jsonb, 0, 'بعد الترتيب: 5، 6، 7، 8، 9، 10، 12. الوسيط = 8، والربيع الأدنى وسيط النصف الأدنى (5، 6، 7) = 6، والربيع الأعلى وسيط النصف الأعلى (9، 10، 12) = 10، فالمدى الربيعي = 10 − 6 = 4.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m101', 'k-central', 3, 'الدرجات التالية تمثل نتائج أربعة طلاب في اختبار الرياضيات: 12، 10، 8، 6. ما المدى الربيعي لهذه الدرجات؟', '["2","3","4","6"]'::jsonb, 2, 'بعد الترتيب: 6، 8، 10، 12. الربيع الأدنى = (6+8) ÷ 2 = 7، والربيع الأعلى = (10+12) ÷ 2 = 11، فالمدى الربيعي = 11 − 7 = 4.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m102', 'k-central', 3, 'احسب الانحراف المتوسط للبيانات التالية: 5، 9، 2، 4', '["2","3","5","6"]'::jsonb, 0, 'المتوسط = 20 ÷ 4 = 5، والانحرافات المطلقة عنه: |5−5|=0، |9−5|=4، |2−5|=3، |4−5|=1، ومجموعها 8، فالانحراف المتوسط = 8 ÷ 4 = 2.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m103', 'k-central', 3, 'احسب التباين للقيم التالية: 6، 4، 2، 4', '["1","1.5","2","2.5"]'::jsonb, 2, 'المتوسط = 16 ÷ 4 = 4، ومربعات الانحرافات: 4، 0، 4، 0 ومجموعها 8، فالتباين = 8 ÷ 4 = 2.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m104', 'k-central', 2, 'عند تحليل نتائج اختبار وُجد أن تباين الدرجات مرتفع. ما الذي يمكن أن يُستنتج من ذلك؟', '["الأداء العام مرتفع","الفروق الفردية واسعة","المتوسط منخفض","مستويات الطلاب متقاربة"]'::jsonb, 1, 'التباين يقيس تشتت الدرجات عن متوسطها؛ فارتفاعه يعني تباعد المستويات واتساع الفروق الفردية، ولا يدل بذاته على ارتفاع الأداء أو انخفاضه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m105', 'k-central', 2, 'إذا كان تباين درجات طلاب الصف في اختبار الرياضيات يساوي 16، فكم يكون الانحراف المعياري لهذه الدرجات؟', '["8","6","5","4"]'::jsonb, 3, 'الانحراف المعياري هو الجذر التربيعي للتباين: √16 = 4.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m106', 'k-central', 3, 'عند مقارنة تشتت مجموعتين أو أكثر بمتوسطات حسابية غير متشابهة فإننا نستخدم:', '["الانحراف المعياري","معامل الالتواء","المدى","معامل الاختلاف"]'::jsonb, 3, 'معامل الاختلاف نسبة مئوية تنسب الانحراف المعياري إلى المتوسط، فيتيح مقارنة تشتت مجموعات تختلف متوسطاتها أو وحدات قياسها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m107', 'k-central', 3, 'أجرى معلم اختبارًا تحصيليًا على 30 طالبًا، وتراوحت درجاتهم بين 4 و10. ما المقاييس الإحصائية الأنسب في هذا السياق؟', '["المنوال والانحراف المتوسط","الوسيط والمدى","المتوسط والانحراف المعياري","النسبة والتباين"]'::jsonb, 2, 'البيانات كمية ومتقاربة وخالية من القيم الشاذة، وفي هذه الحال يكون المتوسط الحسابي أدق مقاييس النزعة المركزية والانحراف المعياري أدق مقاييس التشتت.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m108', 'k-central', 3, 'الدرجات التالية تمثل نتائج مجموعة من الطلاب في اختبار العلوم: 12، 13، 14، 20، 48. أي من مقاييس التشتت التالية يُعد الأنسب لتمثيل تشتت هذه البيانات بدقة؟', '["المدى","الانحراف المعياري","التباين","المدى الربيعي"]'::jsonb, 3, 'القيمة 48 متطرفة وتضخّم المدى والتباين والانحراف المعياري، أما المدى الربيعي فيعتمد على الربيعين ويستبعد الأطراف فلا يتأثر بالشواذ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m109', 'k-correlation', 2, 'كل ما يلي يُعد علاقة ارتباط طردية موجبة، ما عدا:', '["عدد ساعات العمل والدخل","عدد ساعات النوم والأرق","المستوى التعليمي وسرعة القراءة","الترابط الأسري والتحصيل الدراسي"]'::jsonb, 1, 'كلما زادت ساعات النوم قلّ الأرق، فالعلاقة بينهما عكسية (سالبة). أما بقية الخيارات فيزيد فيها المتغيران معًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m110', 'k-correlation', 2, 'إذا كان معامل الارتباط لدرجات الطلاب في اختبارين لمادتين مختلفتين هو 0.2، فإن هذا يعني أن:', '["20% من الطلاب نجحوا في الاختبارين","العلاقة ضعيفة بين المادتين","الاختبارات تمتاز بالصدق والثبات","الاختبارين يتميزان بالسهولة"]'::jsonb, 1, 'معامل الارتباط بين 0.01 و0.49 يدل على ارتباط طردي ضعيف؛ وهو لا يعبر عن نسبة مئوية للناجحين ولا عن صدق الاختبار أو سهولته.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m111', 'k-correlation', 2, 'أرادت باحثة قياس العلاقة بين عدد ساعات المذاكرة الأسبوعية للطلاب ومتوسط درجاتهم في الاختبارات النهائية. ما معامل الارتباط الأنسب لاستخدامه؟', '["معامل فاي","معامل سبيرمان","معامل بوينت-بيسيريال","معامل بيرسون"]'::jsonb, 3, 'المتغيران كميان متصلان والعلاقة بينهما خطية، ومعامل بيرسون هو الأنسب والأدق في هذه الحال.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m112', 'k-correlation', 3, 'أراد أحد الباحثين قياس العلاقة بين جنس الطالب ومشاركته في حصص التقوية المسائية من عدمها. ما معامل الارتباط الأنسب لتحليل هذه العلاقة؟', '["بيرسون","سبيرمان","فاي","بيسيريال"]'::jsonb, 2, 'كلا المتغيرين اسمي ثنائي التقسيم (ذكر/أنثى، شارك/لم يشارك)، ومعامل الاقتران (فاي) هو المخصص للعلاقة بين متغيرين اسميين ثنائيين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m113', 'k-correlation', 3, 'أجرت إحدى الباحثات دراسة لقياس العلاقة بين نوع السؤال (موضوعي أو مقالي) ودرجات الطلاب في الاختبار النهائي. ما معامل الارتباط الأنسب لتحليل هذه العلاقة؟', '["فاي","بوينت-بيسيريال","بيرسون","سبيرمان"]'::jsonb, 1, 'أحد المتغيرين اسمي ثنائي (نوع السؤال) والآخر كمي متصل (الدرجات)، ومعامل بوينت-بيسيريال هو المخصص لهذه الحالة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m114', 'k-correlation', 3, 'أراد المعلم التنبؤ بدرجات الطلاب في اختبار الرياضيات النهائي بالاعتماد على متغيرين: عدد الأيام التي حضرها كل طالب خلال الفصل الدراسي، ومتوسط درجاته في الاختبارات الصفية. ما التحليل الإحصائي الأنسب لهذا الغرض؟', '["تحليل التباين الأحادي","معامل ارتباط بيرسون","الانحدار الخطي البسيط","الانحدار الخطي المتعدد"]'::jsonb, 3, 'المطلوب تنبؤ بمتغير تابع واحد اعتمادًا على أكثر من متغير مستقل، وهذا مجال الانحدار الخطي المتعدد. أما البسيط فيستخدم مع متغير مستقل واحد فقط.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m115', 'k-arith', 1, 'ما ناتج تقريب العدد 344 إلى أقرب مئة؟', '["300","340","350","400"]'::jsonb, 0, 'ننظر إلى رقم العشرات وهو 4، وهو أقل من 5 فنُبقي رقم المئات كما هو ونجعل ما بعده أصفارًا: 300.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m116', 'k-arith', 1, 'ما ناتج تقريب العدد 7.6 إلى أقرب عدد صحيح؟', '["6","7","8","9"]'::jsonb, 2, 'الرقم بعد الفاصلة هو 6 وهو أكبر من 5، فنزيد العدد الصحيح واحدًا ليصبح 8.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m117', 'k-arith', 2, 'ما ناتج: 8 + 2 × (3² − 1)؟', '["20","22","24","26"]'::jsonb, 2, 'نتبع ترتيب العمليات: الأقواس أولًا (3² − 1 = 9 − 1 = 8)، ثم الضرب (2 × 8 = 16)، ثم الجمع (8 + 16 = 24).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m118', 'k-arith', 2, 'ما قيمة س في المعادلة: 3س + 5 = 20؟', '["3","4","5","6"]'::jsonb, 2, 'نطرح 5 من الطرفين: 3س = 15، ثم نقسم على 3: س = 5.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m119', 'k-arith', 3, 'أُجري اختبار مادة الرياضيات يوم الأحد، ومن المقرر أن يُجرى اختبار العلوم بعد 30 يومًا. في أي يوم من أيام الأسبوع سيكون اختبار العلوم؟', '["الاثنين","الثلاثاء","الأربعاء","الخميس"]'::jsonb, 1, 'نقسم 30 على 7 فيكون الباقي 2 (لأن 7 × 4 = 28)، ثم نعد يومين بعد الأحد: الاثنين ثم الثلاثاء.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m120', 'k-arith', 3, 'أُجري اختبار مادة العلوم يوم الثلاثاء، ومن المقرر أن يُجرى اختبار الحاسب الآلي بعد 40 يومًا. في أي يوم من أيام الأسبوع سيكون اختبار الحاسب؟', '["السبت","الأحد","الاثنين","الخميس"]'::jsonb, 1, 'نقسم 40 على 7 فيكون الباقي 5 (لأن 7 × 5 = 35)، ثم نعد خمسة أيام بعد الثلاثاء: الأربعاء، الخميس، الجمعة، السبت، الأحد.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m121', 'k-arith', 2, 'ما العدد الذي يُكمل النمط التالي: 2، 5، 11، 23، .........؟', '["35","47","45","40"]'::jsonb, 1, 'قاعدة النمط: اضرب في 2 ثم أضف 1. (2×2+1=5، و5×2+1=11، و11×2+1=23)، فيكون التالي 23×2+1 = 47.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m122', 'k-arith', 1, 'حصل الطالب خالد على 7.5 درجة في الاختبار الفصلي، و8.25 درجة في الاختبار النهائي. ما مجموع درجاته في المادتين؟', '["15.5","15.75","16","16.25"]'::jsonb, 1, 'نوحّد المنازل العشرية ونجمع: 7.50 + 8.25 = 15.75.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m123', 'k-arith', 1, 'في أحد الاختبارات كل سؤال يُحتسب بـ 1.5 درجة. إذا أجاب الطالب ناصر عن 8 أسئلة إجابة صحيحة، فكم درجة حصل عليها؟', '["9.5","10","12","13.5"]'::jsonb, 2, 'مجموع الدرجات = 1.5 × 8 = 12 درجة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m124', 'k-arith', 2, 'في إحدى إدارات التعليم بلغ عدد الطلاب في المرحلة الابتدائية 12850 طالبًا، وفي المرحلة المتوسطة 11900 طالب، أما المرحلة الثانوية فكان عدد طلابها أقل من طلاب المرحلة المتوسطة بـ 1500 طالب. فما مجموع عدد الطلاب في المراحل الثلاث؟', '["35000","35150","35500","35800"]'::jsonb, 1, 'عدد الثانوية = 11900 − 1500 = 10400، والمجموع = 12850 + 11900 + 10400 = 35150 طالبًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m125', 'k-prob', 3, 'توقعت الرئاسة العامة للأرصاد أن فرصة هطول الأمطار يوم الاثنين هي 80%، وأن فرصة هطول الأمطار يوم الثلاثاء هي 30%. أوجد احتمال هطول الأمطار في يومي الاثنين والثلاثاء معًا.', '["22%","24%","32%","50%"]'::jsonb, 1, 'الحدثان مستقلان، واحتمال وقوعهما معًا = حاصل ضرب الاحتمالين = 0.80 × 0.30 = 0.24 أي 24%.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m126', 'k-prob', 2, 'عند إلقاء مكعب الأرقام (النرد) مرة واحدة، فما احتمالية الحصول على عدد زوجي؟', '["0.1","0.25","0.5","0.75"]'::jsonb, 2, 'الأعداد الزوجية على النرد هي 2 و4 و6 أي 3 نواتج من أصل 6، فالاحتمال = 3 ÷ 6 = 0.5.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m127', 'k-research', 2, 'أراد المعلم فهد دراسة واقع ممارسة الأنشطة القرائية في المدرسة، فقام بإعداد استبانة وتوزيعها على جميع طلاب المدرسة بهدف وصف هذه الظاهرة. فما نوع البحث الذي استخدمه المعلم في هذا السياق؟', '["الوثائقي","التجريبي","الارتباطي","المسحي"]'::jsonb, 3, 'البحث المسحي أحد أنواع المنهج الوصفي، ويجمع البيانات من مجتمع الدراسة (أو عينة كبيرة منه) لوصف واقع ظاهرة كما هي دون تدخل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m128', 'k-research', 3, 'أراد معلم لغة عربية دراسة تطور مهارات القراءة لدى الطلاب، فاختار ثلاث مجموعات من مستويات دراسية مختلفة (الصف الثالث والرابع والخامس)، وقاس مستوى أداء كل مجموعة في القراءة خلال الأسبوع نفسه بهدف استكشاف الفروق النمائية بين هذه الفئات. ما المنهج البحثي المناسب لهذه الدراسة؟', '["النمائي الطولي","السببي المقارن","المسحي الاجتماعي","النمائي المستعرض"]'::jsonb, 3, 'قياس فئات عمرية مختلفة في وقت واحد هو المنهج النمائي المستعرض (العرضي)، بخلاف الطولي الذي يتابع المجموعة نفسها عبر سنوات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m129', 'k-research', 2, 'أراد معلم العلوم التحقق من أثر استخدام التعلم التعاوني على تحصيل الطلاب، فاختار مجموعتين من طلاب الصف السادس، ودرّس إحداهما بالتعلم التعاوني بينما استخدم الطريقة التقليدية مع الأخرى، ثم أجرى اختبارًا موحدًا وقارن النتائج. ما نوع البحث الذي استخدمه المعلم؟', '["المسحي","السببي المقارن","دراسة الحالة","التجريبي"]'::jsonb, 3, 'وجود مجموعة تجريبية وأخرى ضابطة مع تدخل مقصود من الباحث (المتغير المستقل) لقياس أثره في المتغير التابع هو جوهر المنهج التجريبي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m130', 'k-research', 3, 'أراد المعلم أحمد إجراء بحث عن (أثر مستوى الوالدين التعليمي على اتجاهات الطلاب نحو المدرسة). فأي مناهج البحث يستخدمها؟', '["التجريبي","الوصفي","التاريخي","شبه التجريبي"]'::jsonb, 1, 'مستوى الوالدين التعليمي متغير قائم لا يستطيع الباحث التحكم فيه أو تعديله، فيوصف الواقع ويُدرس ارتباطه بالاتجاهات ضمن المنهج الوصفي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m131', 'k-research', 2, 'أي مما يأتي من خصائص الطريقة الطولية في دراسة النمو؟', '["تحتاج عينة كبيرة","تستغرق مدة طويلة","ذات تصميم سهل","نتائجها غير دقيقة"]'::jsonb, 1, 'الطريقة الطولية تتابع الأفراد أنفسهم عبر سنوات فتستغرق وقتًا طويلًا، لكنها دقيقة وتحتاج عينة صغيرة نسبيًا، بعكس الطريقة المستعرضة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m132', 'k-research', 2, 'في بحث بعنوان (أثر استخدام الأنشطة على التقليل من ظاهرة الغياب المدرسي)، يُعد غياب الطلاب متغيرًا:', '["مستقلًا","تابعًا","دخيلًا","وصفيًا"]'::jsonb, 1, 'المتغير التابع هو الذي يُقاس أثر التدخل فيه؛ فالأنشطة متغير مستقل (السبب) والغياب متغير تابع (النتيجة).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m133', 'k-research', 3, 'عينة مختارة عن طريق تقسيم مجتمع الدراسة إلى فئات على أساس بعض المتغيرات الملائمة، ثم اختيار عدد محدد من الحالات من كل فئة حسب حجم هذه الفئة في مجتمع البحث، مع التأكد من أن كل فئة ممثلة في العينة. هذه العينة هي:', '["الطبقية","البسيطة","العمدية","المتيسرة"]'::jsonb, 0, 'العينة الطبقية تُستخدم مع المجتمعات غير المتجانسة، فتُقسَّم إلى طبقات ويُؤخذ من كل طبقة بنسبة حجمها لتكون العينة ممثلة للجميع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m134', 'k-research', 2, 'أراد المعلم فهد اختيار مجموعة من الطلاب كعينة لبحثه، فأعطى الطلاب ترقيمًا متسلسلًا، ثم ولّد أرقامًا عشوائية بالحاسب الآلي، واختار الطلاب الذين تطابقت أرقامهم مع الأرقام المختارة عشوائيًا ليمثلوا عينة البحث. ما العينة التي استخدمها المعلم فهد؟', '["العشوائية البسيطة","العشوائية الطبقية","العشوائية المنتظمة","العشوائية العنقودية"]'::jsonb, 0, 'إعطاء كل فرد فرصة متساوية عبر القرعة أو جداول/برامج الأرقام العشوائية هو تعريف العينة العشوائية البسيطة، وتناسب المجتمع الصغير المتجانس.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m135', 'k-research', 3, 'أراد باحث دراسة اتجاهات المعلمين نحو التقويم التكويني، فطلب من قادة المدارس ترشيح عدد من المعلمين المعروفين باهتمامهم بالتطوير المهني، ثم أجرى مقابلات معمقة معهم. ما نوع العينة التي استخدمها الباحث؟', '["العشوائية البسيطة","الطبقية","القصدية","العينة العنقودية"]'::jsonb, 2, 'اختيار أفراد بعينهم لاعتقاد الباحث أنهم الأنسب لتحقيق هدف الدراسة هو العينة القصدية (العمدية)، وتكثر في البحوث النوعية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
